{topic:"חיפוש",src:"נוסף",q:"שוטר ביקש וקיבל הסכמה לחיפוש בטלפון של חשוד, ומצא הודעות מפלילות. מה הדין?",o:["החיפוש חוקי כי ניתנה הסכמה","החיפוש חוקי כי נמצאו ראיות","החיפוש פסול — חיפוש בטלפון מחייב צו שיפוטי גם בהסכמה (אוריך)","החיפוש חוקי אם הוסבר על הזכות לסרב"],c:2,e:"אוריך: חדירה לחומר מחשב/טלפון מחייבת תמיד צו שיפוטי, גם כשניתנה הסכמה מדעת."},
{topic:"פסילת ראיות",src:"נוסף",q:"מהי ראיה 'עצמאית' לפי יששכרוב ומה נטיית הפסיקה לגביה?",o:["ראיה שתוכנה הושפע מהפגיעה — נוטים לפסול","ראיה שתוכנה לא השתנה בגלל אי-החוקיות (DNA, חפץ) — נוטים להכשיר","הודאה שנמסרה ללא אזהרה — נוטים להכשיר","עדות שמיעה — תמיד נפסלת"],c:1,e:"ראיה עצמאית (חפצית) שתוכנה לא הושפע מהפגיעה בזכויות נוטה להתקבל; ראיה מושפעת (הודאה) נוטה להיפסל."},
{topic:"נוכחות",src:"נוסף",q:"מהו המועד לבקש ביטול החלטה שניתנה בערעור שלא בפני המערער, ומי רשאי?",o:["30 יום, גם המדינה","15 יום, רק הנאשם","30 יום, רק הנאשם","15 יום, גם המדינה"],c:1,e:"בערעור: הביטול תוך 15 יום (לא 30!) ורק ע\"י הנאשם — לא המדינה. נקודת בחינה קלאסית."},
{topic:"מעצר ימים",src:"נוסף",q:"המשטרה מבקשת להאריך מעצר ימים ב-16 יום בעילת מסוכנות. מה הדין?",o:["כדין — מותר עד 20 יום","לא כדין — הארכה בעילת מסוכנות/שיבוש עד 15 יום בכל פעם","כדין אם אושר ע\"י יועמ\"ש","לא כדין — מותר עד 10 יום"],c:1,e:"ס' 17(א): הארכה בעילת שיבוש/מסוכנות עד 15 יום בכל הארכה. 16 יום — לא כדין."},
{topic:"סמכות מקומית",src:"נוסף",q:"נאשם מתגורר קבוע באשקלון (מחוז דרום), שכר דירה זמנית לחודשיים בפ\"ת (מרכז), והעבירה בוצעה בתל-אביב. היכן הסמכות המקומית?",o:["מרכז — מקום המגורים הזמני","דרום או תל-אביב — מגורים קבועים או מקום ביצוע","רק דרום","רק מרכז"],c:1,e:"סמכות מקומית (ס' 6) לפי מקום ביצוע העבירה (ת\"א) או מקום מגורים קבוע (אשקלון). מגורים ארעיים לחודשיים אינם רלוונטיים."},
{topic:"צירוף נאשמים",src:"נוסף",q:"שני נאשמים עברו יחד עבירת פריצה, אך מעורבותם שונה בעוצמתה. לפי דעת הרוב בפס\"ד סוסן, האם ניתן לצרפם בכתב אישום אחד?",o:["לא, כי ס' 87 דורש זהות מוחלטת בעבירה","כן, ס' 86 מאפשר צירוף גם בחצייה עניינית, בכפוף לתנאי ס' 87","כן, אך רק אם שניהם מודים","לא, כי צירוף נאשמים אסור בעבירות רכוש"],c:1,e:"דעת הרוב בסוסן: ס' 86 מהווה עוגן לצירוף נאשמים גם בחצייה עניינית (לא זהות מוחלטת), ובלבד שמתקיימים תנאי ס' 87 (עברו יחד/סייע/עבירה זהה)."},
{topic:"צירוף נאשמים",src:"נוסף",q:"לפי דעת המיעוט של השופט גולדברג בפס\"ד סוסן, מה היחס בין ס' 86 ל-ס' 87 לחסד\"פ?",o:["זהים לחלוטין ואין ביניהם הבדל מעשי","שני מסלולים נפרדים ועצמאיים לצירוף","ס' 87 גובר תמיד על ס' 86","ס' 86 חל רק על נאשם יחיד"],c:1,e:"גולדברג (מיעוט): 86 ו-87 הם שני מסלולי צירוף נפרדים, בניגוד לגישת הרוב שרואה ב-86 עוגן כללי הכפוף לתנאי 87."},
{topic:"צירוף תיקים",src:"נוסף",q:"נאשם שהורשע בבית משפט השלום מבקש כי יידונו במסגרת אותו הליך גם עבירות נוספות שביצע ושבהן הוא מודה, לצורך גזר הדין. התובע מתנגד. מה הדין?",o:["בקשתו תידחה כי רק התובע רשאי לבקש צירוף תיקים","בקשתו יכולה להתקבל — רק הנאשם/בא כוחו רשאים לבקש צירוף לפי ס' 39 לחוק העונשין, בכפוף להודאה ולסמכות עניינית זהה","בקשתו תידחה אוטומטית בשל התנגדות התובע","ניתן לצרף גם תיק שנדון במחוזי לשלום"],c:1,e:"צירוף תיקים (ס' 39 לחוק העונשין) — רק הנאשם/סנגורו רשאים לבקש, בהודאה בלבד, ותוך מתן הזדמנות לתביעה לטעון; לא ניתן לצרף מחוזי לשלום."},
{topic:"נוכחות נאשם",src:"נוסף",q:"נאשם המיוצג בעבירת עוון ביקש מראש שהדיון יתנהל שלא בפניו, וב\"מ מצא כי אין בכך עיוות דין. בסיום ההוכחות הורשע וביהמ\"ש ביקש להטיל עליו מאסר בפועל. האם ניתן?",o:["כן, כי הנאשם ביקש זאת מראש", "לא — לעולם אין להטיל מאסר בפועל (או על תנאי) שלא בפני הנאשם, גם אם ביקש זאת", "כן, בעוון מותר תמיד", "לא, אלא אם כן אישר זאת הסנגור בכתב"],c:1,e:"ההגבלה על מאסר שלא בפני הנאשם מוחלטת — לא ניתן להטילו (כולל על-תנאי ועבודות שירות) גם כשההיעדרות עצמה כדין; קנס בלבד מותר בעוון/חטא."},
{topic:"עיכוב הליכים",src:"נוסף",q:"תובע מחוזי סבור כי יש לעכב הליכים נגד נאשם בשל שיקולים ציבוריים כבדי משקל. מי מוסמך להחליט על עיכוב הליכים לפי ס' 231 לחסד\"פ?",o:["התובע המחוזי בעצמו","בית המשפט הדן בתיק","היועץ המשפטי לממשלה בלבד","פרקליט המדינה או התובע, לפי חומרת העבירה"],c:2,e:"סמכות עיכוב הליכים נתונה ליועמ\"ש לממשלה בלבד — לא לתובע ולא לבית המשפט, שאף אינו יכול להתערב בשיקול דעתו."},
{topic:"פסלות שופט",src:"נוסף",q:"עורך דין גילה כי השופט הדן בתיקו למד באותה כיתה עם התובע לפני 25 שנה, ואינם בקשר. האם קמה עילת פסלות?",o:["כן — כל היכרות קודמת עם צד פוסלת אוטומטית","ככל הנראה לא — נבחן לפי מבחן 'האפשרות הממשית למשוא פנים' (ידיד), וקשר רופף וישן אינו מגיע לרף זה","כן, מכוח ס' 77א לחוק בתי המשפט (קרבת משפחה)","לא ניתן לדעת ללא פנייה ליועמ\"ש"],c:1,e:"ס' 77א חל על קרבת משפחה, לא היכרות מקרית. לפי ידיד, נבחנת אפשרות ממשית למשוא פנים — קשר רופף מהעבר הרחוק ככלל אינו מספיק."},
{topic:"הגנה מן הצדק",src:"נוסף",q:"מהו השלב השלישי במבחן בורוביץ' התלת-שלבי להגנה מן הצדק?",o:["זיהוי הפגם ועוצמתו במנותק מהאשמה","בחינת האם קיים דמיון רלוונטי לנאשמים אחרים","בחינה האם ניתן לרפא את הפגיעה בסעד מידתי פחות מביטול, לפני שפונים לביטול כתב האישום","בדיקת התיישנות העבירה"],c:2,e:"שלב 3 בבורוביץ': לאחר זיהוי הפגם (שלב 1) ואיזון האינטרסים (שלב 2), יש לבחון האם ניתן לרפא בסעד מתון יותר מביטול — ורק אם התוצאה 'בלתי נסבלת' יבוטל כתב האישום."},
{topic:"אכיפה בררנית",src:"נוסף",q:"נאשם טוען לאכיפה בררנית כי חברו לעבירה לא הועמד לדין. מה עליו להוכיח כתנאי מפתח לטענה, ועל מי הנטל?",o:["רק שהוא לא ביצע את העבירה; הנטל על התביעה","דמיון רלוונטי בין מצבו לבין מי שלא הועמד לדין + שההבחנה נובעת מפשר אסור; הנטל על הנאשם","שהתובע לא נימק את החלטתו; הנטל על התביעה","די בכך שהעבירה זהה; אין נטל הוכחה"],c:1,e:"דרישת הדמיון הרלוונטי: הנאשם (עליו הנטל) חייב להראות דמיון רלוונטי למי שלא הועמד לדין, ושההבחנה נובעת מפשר אסור (ולא שיקול לגיטימי)."},
{topic:"פגם/פסול בכ\"א",src:"נוסף",q:"כתב אישום הושמט ממנו סעיף החיקוק הרלוונטי לאחת העבירות המיוחסות, אך העובדות תוארו במלואן. כיצד יסווג הפגם וכיצד יש לנהוג?",o:["פסול — יש לבטל את כתב האישום מיידית","פגם — חסר תוכן (השמטת הוראת חיקוק); ייבחן לפי דוקטרינת הבטלות היחסית האם קיפח את ההגנה","אין בכך פגם כלל, כי העובדות מספיקות","יש להאשים את הנאשם בעבירה אחרת באופן אוטומטי"],c:1,e:"השמטת הוראת חיקוק היא 'פגם' (חסר תוכן) ולא 'פסול' (הפרת דרישת הגשה). התוצאה נבחנת לפי בטלות יחסית — האם נגרם קיפוח בפועל."},
{topic:"תיקון כתב אישום",src:"נוסף",q:"התביעה מבקשת לתקן את כתב האישום שבועיים לאחר ההקראה, כך שיתווסף אישום נוסף. מה הדין?",o:["התיקון חופשי לחלוטין כמו לפני הקראה","נדרשת רשות בית המשפט, שיאשר רק אם אין בכך קיפוח להגנת הנאשם (ס' 92)","לא ניתן לתקן כתב אישום לעולם אחרי הקראה","ניתן לתקן רק בהסכמת הנאשם בלבד, ללא ביהמ\"ש"],c:1,e:"ס' 92 — לאחר ההקראה תיקון כתב אישום טעון רשות בית המשפט, שתינתן רק אם אין בכך כדי לקפח את הגנת הנאשם."},
{topic:"חזרה מאישום",src:"נוסף",q:"התובע חוזר בו מכתב האישום מיד לאחר הגשתו, לפני שהנאשם השיב לאישום. מהי התוצאה המשפטית?",o:["זיכוי — מעשה בית דין החוסם הגשה מחדש","ביטול כתב האישום — אינו מעשה בית דין, וניתן להגיש כתב אישום חדש באותו עניין","התיישנות מיידית","הרשעה אוטומטית בעבירה קלה יותר"],c:1,e:"חזרה מאישום לפני מענה הנאשם = ביטול כ\"א בלבד — אינו מעשה בית דין, ולכן ניתן להגיש כתב אישום חדש (בשונה מחזרה לאחר כפירה/הודאה חלקית, שהיא זיכוי)."},
{topic:"סדר הדיון",src:"נוסף",q:"נאשם שבחר להעיד בפרשת ההגנה — האם חייב לחשוף מראש את קו הגנתו לתביעה?",o:["כן, תמיד חייב לגלות את קו ההגנה מראש","לא חייב, למעט טענת אליבי החייבת בהודעה מוקדמת", "כן, אך רק בעבירות פשע", "לא חייב בשום מקרה, כולל אליבי"],c:1,e:"ככלל אין חובת גילוי מוקדם של קו הגנה, אך טענת אליבי מחייבת הודעה מוקדמת כדי לאפשר לתביעה לבדוק אותה."},
{topic:"התיישנות",src:"נוסף",q:"מהי תקופת ההתיישנות של עבירה שדינה מאסר עולם?",o:["7 שנים","10 שנים","15 שנה","20 שנה"],c:3,e:"ס' 9 — עבירה שדינה מאסר עולם מתיישנת ב-20 שנה; פשע חמור (מעל 7 שנים) — 10 שנים; פשע רגיל — 7 שנים; עוון — 5 שנים; חטא/קטין — שנה."},
{topic:"התיישנות",src:"נוסף",q:"מהי דוגמה ל'אירוע מנתק' תקופת התיישנות, לפי הפסיקה (לרבות אבנר שקי)?",o:["ישיבת התייעצות פנימית בפרקליטות ללא כל פעולה כלפי חוץ","פעולת חקירה, הגשת כתב אישום, או קיום הליך בבית המשפט","פרסום כתבה עיתונאית על הפרשה","חלוף הזמן בלבד"],c:1,e:"אירועים מנתקים: פעולת חקירה, הגשת כ\"א, הליך בב\"מ. אבנר שקי הבהיר שפעולות תביעה פנים-ארגוניות לאחר סיום החקירה אינן מנתקות."},
{topic:"סיכון כפול",src:"נוסף",q:"מהו הרף הנדרש כדי שתקום טענת 'סיכון כפול' הפסיקתית, להבדיל מ'כבר זוכיתי' (149(5))?",o:["רק הכרעת דין סופית מזכה", "די בכך שהנאשם 'עמד בסיכון' — למשל שנפתח הדיון והוגשו ראיות — גם ללא הכרעת דין", "רק הרשעה קודמת בעבירה זהה", "יש להוכיח כי הנאשם ריצה עונש בפועל"],c:1,e:"סיכון כפול הפסיקתי דורש רק ש'עמד בסיכון' (למשל נשמעו עדי תביעה), בשונה מ'כבר זוכיתי' הדורשת פסק דין מזכה/מרשיע בפועל."},
{topic:"חיפוש",src:"נוסף",q:"שוטר עצר אישה ברחוב ודרש ממנה תעודת זהות ללא כל חשד סביר, ולאחר מכן, בעודה מזדהה, ערך גם חיפוש בתיקה. מה הדין לפי עמותת טבקה?",o:["שני הצעדים כדין, כי הצגת ת\"ז מספיקה להצדיק הכל","דרישת הת\"ז יכולה להיות כדין בנסיבות מסוימות, אך החיפוש בתיק — פעולת שיטור נוספת — טעון חשד סביר נפרד ואינו כדין כאן","שני הצעדים אינם כדין בשום מקרה","החיפוש כדין כי ניתנה תעודת הזהות מרצון"],c:1,e:"עמותת טבקה: ניתן לדרוש ת\"ז ללא חשד סביר בנסיבות ספציפיות, אך אין להשתמש בכך כבסיס לפעולות שיטור נוספות (כגון חיפוש) ללא חשד סביר עצמאי."},
{topic:"כוח קטלני",src:"נוסף",q:"שוטר ירה והרג חשוד שנמלט מזירת גניבת אופניים (עוון). האם הירי חוקי לפי גולד ואנקונינה?",o:["כן, כל עוד המעצר עצמו היה חוקי","לא — התנאי השני (פשע המסכן חיי אדם/גוף) אינו מתקיים כלל בעבירת גניבה מסוג עוון","כן, כי מדובר באמצעי אחרון","כן, אם ניתנה אזהרה מילולית בלבד"],c:1,e:"3 התנאים המצטברים כוללים פשע המסכן חיי אדם/גוף. גניבת אופניים היא עוון, שאינו מסכן חיים כלל — הירי אסור ואינו נבחן כלל לפי שאר התנאים."},
{topic:"שימוע",src:"נוסף",q:"חשוד עצור ברציפות מרגע העברת חומר החקירה לתביעה ועד הגשת כתב האישום, שהוגש בעודו עצור. האם חלה עליו חובת שימוע לפי ס' 60א'?",o:["כן, חובת השימוע חלה תמיד בפשע ללא יוצא מן הכלל","לא — חל הפטור שבס' 60א'(ז) למי שהיה עצור ברציפות בעת העברת חומר החקירה והגשת כתב האישום", "כן, אלא אם החשוד מוותר על כך בכתב", "לא, כי שימוע נדרש רק בעוון"],c:1,e:"ס' 60א'(ז) פוטר מחובת שימוע כאשר החשוד עצור ברציפות בעת העברת חומר החקירה וכתב האישום מוגש בתוך תקופת המעצר."},
{topic:"סמכות עניינית",src:"נוסף",q:"כתב אישום מייחס לנאשם עבירת סחיטה באיומים (עונש מרבי 9 שנים) שאינה מנויה בחלק א' לתוספת הראשונה לחוק בתי המשפט. הוגש למחוזי. באיזה הרכב יידון?",o:["דן יחיד תמיד במחוזי","הרכב של שלושה שופטים, כי העונש מעל 10 שנים","הרכב של שלושה שופטים אינו נדרש — פחות מ-10 שנות מאסר; ידון בדן יחיד", "יש להעביר לבית משפט השלום בהכרח"],c:2,e:"הרכב שלושה נדרש רק בעבירה שדינה 10 שנות מאסר ומעלה שאינה בחלק א' לתוספת. 9 שנים אינן חוצות את הרף — דיון בדן יחיד."}
